// МОЙ СКРИПТ

frappe.provide("frappe.treeview_settings");

let proxy = new Proxy(frappe.treeview_settings, {
    set(target, prop, val) { // для перехвата записи свойства
        if ( (prop != "Task") || (prop == "Task" && !target[prop]) ) {
            target[prop] = val;
        }
        return true;
      }
});

frappe.treeview_settings = proxy;

frappe.treeview_settings["Task"] = {
    get get_tree_nodes() {
        console.log("get_tree_nodes");
        return "custom_task_get_children";
    },
    add_tree_node: "erpnext.projects.doctype.task.task.add_node",
    /**get breadcrumb() {
        console.log("breadcrumb");
        return {
			label: "Мои проекты",
			type: "Custom",
			route: "../../../app/мои-проекты",
		};
    },/**/
    get_tree_root: false,
    root_label: localStorage.getItem( frappe.user.name + ":tree:project" ) || __("Все задачи"),
    get title() { return __("Структурный план проекта") },
    ignore_fields: ["parent_task"],
    filters: [
        {
            fieldname: "project",
            fieldtype: "Link",
            options: "Project",
            label: __("Project"),
            reqd: 1,
            //default: localStorage.getItem( frappe.user.name + ":tree:project" ),
            get default() {
                let value = localStorage.getItem( frappe.user.name + ":tree:project" )
                return value;
            },
            set default(value) {
                localStorage.setItem( frappe.user.name + ":tree:project", value );
            },/**/
            onchange: function () {
                console.log("Изменение фильтра.");
                let old_value = cur_tree?.view?.page?.fields_dict?.project?.last_value;
                let value = cur_tree?.view?.page?.fields_dict?.project?.get_value();
                if ( value ) {
                    localStorage.setItem( frappe.user.name + ":tree:project", value );
                } else if ( old_value ) {
                    cur_tree.view.page.fields_dict.project.set_value( old_value );
                }
            },
            disable_onchange: false,
        },
        
        //Необходимо починить фильтр
        {
            fieldname: "task",
            fieldtype: "Link",
            options: "Task",
            label: __("Task"),
            get_query: function () {
                var project = cur_tree.view.page.fields_dict.project.get_value();
                var args = [["Task", "is_group", "=", 1]];
                if (project) {
                    args.push(["Task", "project", "=", project]);
                }
                return {
                    filters: args,
                };
            },
        },
        {
            fieldname: "status",
            fieldtype: "Select",
            //fieldtype: "Table",
            get options() {
                var opts = getStatuses();
                opts.push("");
                return opts;
            },
            label: __("Status"),
            get_query: function () {
                return {};
            },
            onchange: function () {
                console.log("Изменение фильтра.");
                return {};
            },
            disable_onchange: false,
        },
        {
            fieldname: "priority",
            fieldtype: "Select",
            get options() {
                var opts = getPriorities();
                opts.push("");
                return opts;
            },
            label: __("Priority"),
            get_query: function () {
                return {};
            },
            onchange: function () {
                console.log("Изменение фильтра приоритета.");
                return {};
            },
            disable_onchange: false,
        },
        
        
        //Необходимо починить фильтр
        {
            fieldname: "assign",
            fieldtype: "Link",
            options: "User",
            label: __("Assigned To"),
            onchange: function () {
                console.log("Изменение фильтра assign.");
                return {};
            },
            disable_onchange: false,
        },
        {
            fieldname: "tag",
            fieldtype: "Link",
            options: "Tag",
            label: __("User Tags"),
            onchange: function () {
                console.log("Изменение фильтра Tag.");
                return {};
            },
            disable_onchange: false,
        },
        {
            fieldname: "limit",
            fieldtype: "Int",
            label: __("Limit"),
            /*get default() {
                return 200;
            },/**/
        },
    ],
    /*menu_items: [
        {
            label: 'New action',
            action: {},
            condition: true
        }
    ],*/

    onload: function (me) {
        me.make_tree = makeTreeDecorator( me.make_tree );
        //me.make_tree();
    },
    click: function ( node ) {
        if ( node.is_root && node.expandable ) {
            cur_tree.toggle_node( node );
            node.expandable = false;
            node.expanded = true;
        }/**/
        if ( node.loaded ) {
            makeResizable();
        }
        if ( !node.expandable || ( node.expandable && node.loaded ) ) {
            click_node_gantt( cur_tree, node.data, node.expanded );
        }
    },
    post_render: function(treeview) {
        // triggered when tree is instanciated
        console.log("post_render");
        toolbarRedesign(treeview.tree);
        makeResizable();
        build_task_tree_layout( treeview );
        
        /**if ( typeof build_task_gantt === 'function' ) {
            build_task_gantt( treeview.tree, treeview.tree.nodes );
        }/**/
        
        treeview.tree.view = treeview;
        //Добавление метода сортировки дерева
        treeview.tree.sort = async function(field, order) {
            console.log("sort " + field + ":" + order );
            var sort = field + " " + order;
            //Добавляем параметр сортировки для передачи в Server Script
            this.args.sort = sort;
            this.args.sort_field = field;
            this.args.sort_order = order;
            let expNodes = [];
            
            //Сохраняем все открытые ветки дерева (чтобы заново открыть после загрузки)
            for (const nodeID in this.nodes) {
                let node = this.nodes[nodeID];
                if ( node.expanded && node.expandable && node.label != this.root_value ) {
                    expNodes.push( nodeID );
                } 
            }
            
            let tasks = [
                //Загружаем корневую ветку с учетом сортировки
                () => this.load_children(this.root_node, false)
                ];
            
            //Загружаем открытые ветки дерева с учетом сортировки
            for (const nodeID of expNodes) {
                tasks.push( 
                    () => {
                        let node = this.nodes[ nodeID ];
                        node.loaded=false;
                        return this.load_children( node, false);
                    }
                    );
            }
            
            //Запуск функций строго последовательно
            frappe.run_serially(tasks);/**/
        }
        
        //Функция-обертка вокруг функции получения списка дочерних задач
        function get_nodes_decorator(tree) {
            const original_get_nodes = tree.get_nodes;
            
            tree.get_nodes = async function(value, is_root, update_gantt = true) {
                console.log("get_nodes_decorator" );
                let result = await original_get_nodes.call( tree, value, is_root );
                
                if ( update_gantt ) {
                    add_nodes_to_gantt( cur_tree, result );
                }
                
                return result;
            };
            return tree;
        }
        
        treeview.tree = get_nodes_decorator( treeview.tree );
        
        //Исправление метода get_all_nodes, загружающего всё дерево (Expand All)
        treeview.tree.get_all_nodes = async function(value, is_root, label) {
            //Добавляем параметр Server Script для выгрузки всего перечня задач
            this.args.is_all = true;
            //Вместо некорректного метода вызываем get_nodes
            let nodes = await this.get_nodes(value, is_root, false);
            let results = [];
            let parents = [];
            
            //Формируем результат, аналогичный методу get_all_nodes
            let addResults = function(results, parents, nodes, curNode) {
                let parent = curNode.parent_task || "";
                
                if ( !parents.includes( parent ) ) {
                    parents.push( parent );
                    let parentNode = nodes.filter((node) => ( node.value == parent ) )[0];
                        
                    if (parentNode) {
                        addResults( results, parents, nodes, parentNode );
                    }
                    
                    if (parentNode || !parent) {
                        let parentData = nodes.filter((node) => ( ( node.parent_task || "" ) == parent ) );
                        results.push({ parent: ( parent ? parent : value ), data: parentData });
                    }
                }
            };
            
            for (const node of nodes) {
                addResults( results, parents, nodes, node );
            }
                    
            this.args.is_all = null;
            
            let sortedNodes = [];
            //Сортировка nodes с учетом вложенности для отображения на графике
            let getChildrenNodes = function(results, nodes, parent) {
                for ( node of nodes.filter( n => n.parent_task == parent ) ) {
                    results.push( node );
                    getChildrenNodes( results, nodes, node.value );
                }
            }
            getChildrenNodes( sortedNodes, nodes, null );
            add_nodes_to_gantt( this, sortedNodes );
            return results;
        }
        
        //Изменение иконок дерева
        //https://discuss.frappe.io/t/all-the-frappe-icons-overview/78762
        cur_tree.icon_set = {
			open: frappe.utils.icon("down", "xs"),
			closed: frappe.utils.icon("right", "xs"),
			leaf: "",
			//open: frappe.utils.icon("es-minus", "md"),
			//closed: frappe.utils.icon("es-plus", "md"),
			//leaf: frappe.utils.icon("primitive-dot", "xs"),
		};/**/
    },
    onrender: function(node) {
        // console.log("onrender" );
        // triggered when a node is instanciated
        if (!node.is_root) {
            //Добавляем дополнительные колонки с данными
            node.parent.find(".tree-row").remove();
            
            node.$row = $(  "<div class='tree-row" + ( node.data.can_write ? " edit" : "" ) + "'>" +
                    "<span class='details-area'" +
                        ( node.data.color ? "style='box-shadow: -4px 0px 4px 2px " + node.data.color + " inset;'" : "" ) + ">" +
                        "<div class='details-cell assign'>" + createAssignmentAvatars( node.data.assign ? JSON.parse(node.data.assign) : [] ) + "</div>" +
                        "<div class='details-cell hours'>" + planFactButton( node.data.value ) + "</div>" +
                        "<div class='details-cell status " + toClass( node.data.status ) + "'>" + node.data.status + "</div>" +
				        "<div class='details-cell priority " + toClass( node.data.priority ) + "'>" + node.data.priority + "</div>" +
				        //"<div class='details-cell plan-start'>" + ( node.data.custom_planned_start_date ? frappe.format( node.data.custom_planned_start_date, {'fieldtype': 'Date' } ) : "&nbsp;" ) + "</div>" +
				        //"<div class='details-cell plan-end'>" + ( node.data.custom_planned_end_date ? frappe.format( node.data.custom_planned_end_date, {'fieldtype': 'Date' } ) : "&nbsp;" ) + "</div>" +
				        "<div class='details-cell exp_start_date'>" + ( node.data.exp_start_date ? frappe.format( node.data.exp_start_date, {'fieldtype': 'Date' } ) : "&nbsp;" ) + "</div>" +
				        "<div class='details-cell exp_end_date'>" + ( node.data.exp_end_date ? frappe.format( node.data.exp_end_date, {'fieldtype': 'Date' } ) : "&nbsp;" ) + "</div>" +
				        "<div class='details-cell duration'>" + ( node.duration ? node.duration : "-" ) + "</div>" +
                        "<div class='details-cell progress' title='" + node.data.progress + "%'>" + creareProgress( node.data.progress ) + "</div>" +
                        "<div class='details-cell timesheet'>" +
                            "<input type='checkbox' " + ( node.data.custom_include ? 'checked' : '' ) + " class='include-checkbox' onclick='return false;'></div>" +
                        "<div class='details-cell type'>" + ( node.data.type ? node.data.type : "&nbsp;" ) + "</div>" +    
				        "<div class='details-cell user_tag'></div>" +
				    "</span>" +
				"</div>"
            ).insertBefore(node.$ul);
            //
            
            //Добавляем выпадающие списки для статуса и приоритета
            createControl(node.$row.find(".details-cell.status"), node.data, "status", "Select", getStatuses );
            createControl(node.$row.find(".details-cell.priority"), node.data, "priority", "Select", getPriorities );
            
            //Добавляем селекторы для плановыз дат начала и завершения
            createControl( node.$row.find('.details-cell.plan-start'), node.data, 'custom_planned_start_date', 'Date' );
            createControl( node.$row.find('.details-cell.plan-end'), node.data, 'custom_planned_end_date', 'Date' );
            
            //Добавляем селекторы для прогнозных дат начала и завершения
            createControl( node.$row.find('.details-cell.exp_start_date'), node.data, 'exp_start_date', 'Date' );
            createControl( node.$row.find('.details-cell.exp_end_date'), node.data, 'exp_end_date', 'Date' );
            
            //Добавляем редактор для наименования задачи
            createControl( node.parent.find('.tree-label'), node.data, 'subject', 'Data' );
            node.parent.find('.tree-label').attr('title', node.data.value ); 
            
            //Добавляем чекбокс для индикатора включения в ТШ
            createControl( node.$row.find('.details-cell.timesheet'), node.data, 'custom_include', 'Check' );
            
            //Добавляем диалог для назначения ответственных (assign to)
            createAssignmentDialog( node.$row.find( ".details-cell.assign" ), node.data );
            
            //Добавляем метки задач
            createTags( node.$row.find('.details-cell.user_tag'), node.data.user_tags || "", 2, true);
            
            //Изменяем вложенность стандартных элементов
            if (node.$tree_link && node.$toolbar) {
                node.$tree_link.insertBefore(node.$row.find(".details-area"));
                node.$tree_link.append(node.$toolbar);
                node.$tree_link.on( "mouseenter", () => highlight_node_gantt( cur_tree, node, true ) );
                node.$tree_link.on( "mouseleave", () => highlight_node_gantt( cur_tree, node, false ) );
                
                if ( node.data.color ) {
                    node.$tree_link.css("box-shadow", "4px 0px 4px 2px " + node.data.color + " inset");
                }
                
                if ( node.data.is_milestone ) {
                    node.$tree_link.children("span:first-child").append("<img height='14' width='14' alt='milestone' src='/files/rhombus.png'>");
                }
            }
        }
        
        if (node.is_root) {
            //Добавляем заголовок таблицы
            $(".tree-header").remove();
            $("#page-Tree\\/Task .layout-main-section").append(
                "<div class='tree-header'>" +
                    "<div class='tree-row header'>" +
                        "<div class='tree-link header'>" +
                            "<div class='main-col'>" +
                                "<span>" + __("Задача") + "</span></div></div>" +
                        "<span class='details-area header'></span></div></div>"
            );
            
            var sort = ( cur_tree ? cur_tree.args.sort : "") || "";
            const is_asc = sort.includes(" asc");
            
            headers = $(".details-area.header");
            createColumnHeader( headers, __("Ответств."), "_assign", false, false, false );
            createColumnHeader( headers, __("ТРЗ"), "hours", false, false, false );
            createColumnHeader( headers, __("Статус"), "status", true, sort.includes("status"), is_asc );
            createColumnHeader( headers, __("Приоритет"), "priority", true, sort.includes("priority"), is_asc );
            //createColumnHeader( headers, __("План начала"), "custom_planned_start_date", true, sort.includes("custom_planned_start_date"), is_asc );
            //createColumnHeader( headers, __("План завершения"), "custom_planned_end_date", true, sort.includes("custom_planned_end_date"), is_asc );
            createColumnHeader( headers, __("Прогноз начала"), "exp_start_date", true, sort.includes("exp_start_date"), is_asc );
            createColumnHeader( headers, __("Прогноз завершения"), "exp_end_date", true, sort.includes("exp_end_date"), is_asc );
            createColumnHeader( headers, __("Длит-сть"), "expected_time", true, sort.includes("expected_time"), is_asc );
            createColumnHeader( headers, __("Прогресс"), "progress", true, sort.includes("progress"), is_asc );
            createColumnHeader( headers, __("ТШ"), "custom_include", false, false, false );
            createColumnHeader( headers, __("Тип"), "type", false, false, false );            
            createColumnHeader( headers, __("Метки"), "_user_tags", false, false, false );
            
            $(".tree-table").remove();
            $("#page-Tree\\/Task .layout-main-section").append("<div class='tree-table'></div>");
            $(".tree-table").append($(".tree"));
            node.$tree_link.append(node.$toolbar);
            
            //Открыть проект
            node.$tree_link.on('dblclick', function (event) {
                frappe.set_route('Form', "Project", cur_tree?.view?.page?.fields_dict?.project.get_value() );
            });
            
            //Симуляция второго горизонтального скроллбара наверху таблицы
            $(function() {
              $(".tree-table").scroll(function() {
                $(".tree-header").scrollLeft($(".tree-table").scrollLeft());
              });
              $(".tree-header").scroll(function() {
                $(".tree-table").scrollLeft($(".tree-header").scrollLeft());
              });
            });
            
            $("#task-gantt").empty();
            //Фиксация заголовка таблицы при прокрутке вниз
            /**$(function() {
                let header = $('.tree-header');
                $(window).scroll(function() {
                    let topHeight = $(".page-head").outerHeight(true) + $(".page-form").outerHeight(true);
                    if($(this).scrollTop() > topHeight) {
                        header.addClass('header-fixed');
                    } else {
                        header.removeClass('header-fixed');
                    }
                });
            });/**/
        }
    },
    on_get_node: function (nodes, deep = false) {
        // triggered when `get_tree_nodes` returns nodes
        console.log("on_get_node" );
        const can_write = frappe.model.can_write("Task");
        
        for (const node of nodes) {
            node.can_write = can_write && frappe.perm.has_perm("Task", 0, "write", node.value);
            Object.defineProperty(node, 'title', { get: function() { return this.subject;  } });
        }
        refresh_tree_limits( cur_tree?.root_value, nodes );
        refresh_tree_dependencies( cur_tree?.root_value, nodes );
    },
    // enable custom buttons beside each node
    extend_toolbar: true,
    // custom buttons to be displayed beside each node
    toolbar: [
    {
        label: (" "),
        btnClass: 'fa fa-tasks hidden-xs',
        condition: function (node) {
            return frappe.model.can_create("Task") && node.data.can_write;
        },
        click: function (node) {
            this.data = [];
            const dialog = new frappe.ui.Dialog({
                title: ("Add Multiple Tasks"),
                fields: [
                    {
                        fieldname: "multiple_tasks",
                        fieldtype: "Table",
                        in_place_edit: true,
                        data: this.data,
                        get_data: () => {
                        return this.data;
                    },
                    fields: [
                        {
                            fieldtype: "Data",
                            fieldname: "subject",
                            in_list_view: 1,
                            reqd: 1,
                            label: ("Subject"),
                        },
                    ],
                    },
                ],
                primary_action: function () {
                    dialog.hide();
                    return frappe.call({
                        method: "erpnext.projects.doctype.task.task.add_multiple_tasks",
                        args: {
                            data: dialog.get_values()["multiple_tasks"],
                            parent: node.data.value,
                        },
                        callback: function () {
                            node.expandable = true;
                            cur_tree.load_children(node);
                        },
                    });
                },
                primary_action_label: ("Create"),
            });
            dialog.show();
        },
    },
    {
        label: (" "),
        btnClass: 'fa fa-level-down hidden-xs',
        condition: function (node) {
            return ( !node.is_root && node.data.can_write && typeof _tds_preview_tree === 'function' );
        },
        click: function (node) {
            _tds_preview_tree(node.data.value, "downstream", (mode, changes)=> {
                if ( mode == "async" ) {
                    frappe.show_alert(__('Обновите дерево задач после выполнения изменений'));
                } else {
                    changes.forEach(function(change) {
                        frappe.model.clear_doc( "Task", change.task );
                        setNodeValue( change.task, "exp_start_date", change.proposed_start );
                        setNodeValue( change.task, "exp_end_date", change.proposed_end );
                        update_node_gantt( cur_tree, cur_tree?.nodes[ change.task ]?.data );
                    });
                }
            } );
        },
    },
    /*{
        label: (" "),
        btnClass: 'fa fa-long-arrow-left hidden-xs',
        condition: function (node) {
            return ( !node.is_root && node.data.can_write );
        },
        click: function (node) {
            console.log("click");
        },
    },
    {
        label: (" "),
        btnClass: 'fa fa-long-arrow-right hidden-xs',
        condition: function (node) {
            return ( !node.is_root && node.data.can_write );
        },
        click: function (node) {
            console.log("click");
        },
    }/**/
    ],
};

//Функция-обертка вокруг стандартного обработчика создания дерева
function makeTreeDecorator(func) {
    return function() {
        console.log("makeTreeDecorator" );
        let project = frappe.route_options?.project;
        if ( project && project != this.root_label ) {
            this.page.fields_dict.project.set_input(project);
            this.page.fields_dict.project.df.default = project;
            this.args["project"] = project;
            this.set_title();
        }
        
        frappe.route_options.project = null;
        this.root_label = this.args["project"] || this.page.fields_dict.project.df.default;
        setProjectName( this.root_label );
        resizeLoaded = false;
        
        if ( this.root_label == __("Все задачи") && !this.args["limit"] ) {
            const LIMIT = 200;
            this.page.fields_dict.limit.set_input( LIMIT );
            this.args["limit"] = LIMIT;
        }
        
        return func.apply(this, arguments);
    };
}

function setProjectName(project) {
    if ( project && project != "" ) {
        frappe.db.get_value("Project", project, "project_name")
            .then(function(r) {
    			let prj = r?.message?.project_name;
    			if ( prj ) {
        			let root_element = ".tree-table .tree-link[data-label='" + project + "'] .tree-label";
        			$(root_element).text( prj );
        			cur_tree.view.page.set_title( prj + " (" + project + ")" );
    			}
            }).catch(function(e) {
                console.error(e);
            });
    }
}

function createColumnHeader(element, column, field_name, is_sortable, is_sorted, is_asc ) {
    //Иконки: https://fontawesome.com/v4/icons/
    var header = $("<div class='details-cell header' data-field='" + field_name + "'>" + 
            "<span class='header-title'>" + column + "</span>" +
            "<span class='header-icon" + ( is_sortable ? ( " fa fa-sort" + ( is_sorted ? ( is_asc ? "-asc" : "-desc" )  : "" ) ) : "" )+ "'></span>" +
        "</div>");
        
    element.append(header);
    
    //Событие клика по иконке сортировки
    header.find(".header-icon").on( "click", {field: field_name}, function(ev) {
        var order;
        
        if ( $(this).hasClass( "fa-sort" ) || $(this).hasClass("fa-sort-desc") ) {
            //По возрастанию
            order = "asc";
        } else {
            //По убыванию
            order = "desc";
        }
        //Сброс остальных сортировок
        $(".header-icon.fa-sort-desc").removeClass("fa-sort-desc").addClass("fa-sort");
        $(".header-icon.fa-sort-asc").removeClass("fa-sort-asc").addClass("fa-sort");
        $(this).removeClass("fa-sort").addClass( "fa-sort-" + order );
        
        if (cur_tree.sort) {
            cur_tree.sort(ev.data.field, order);
        }
    });
}

