function evaluate_read_only_depends_on(expression, data) {
	let out = null;
	if (typeof expression === "boolean") {
		out = expression;
	} else if (expression.substr(0, 5) == "eval:") {
		out = frappe.utils.eval(expression.substr(5), { doc: data });
	} else {
		var value = data[expression];
		if ($.isArray(value)) {
			out = !!value.length;
		} else {
			out = !!value;
		}
	}
	return out;
}

//Создаем контролы ввода
//https://frappeframework.com/docs/user/en/api/controls
function createControl(element, node, field_name, field_type, optionsFunc = null ) {
    if ( node.can_write ) {
        //Ловим событие клика по ячейке
        element.on( "click", { node: node, field_name: field_name, field_type: field_type }, function( ev ) {
            frappe.model.with_doc('Task', node.value ).then(doc => {
                node.doc = doc;
                if ( frappe.workflow.is_read_only( "Task", node.value ) ) return;
                element.off( "click");
                $( this ).empty();
                
                //Создаем новый контрол ввода
                let control = frappe.ui.form.make_control({
                    parent: $( this ),
                    doctype: "Task",
                    docname: node.value,
                    df: {
                        label: ( field_type == "Check" ) ? "" : ev.data.field_name,
                        fieldname: ev.data.field_name,
                        fieldtype: ev.data.field_type,
                        options: optionsFunc ? optionsFunc( node ) : null,
                        node: ev.data.node,
                        get_status: function( control ){
                            let df = frappe.meta.get_field("Task", this.fieldname, node.value);
                            let status = frappe.perm.get_field_display_status( df, node.doc, null, false );
                            if ( status === "Write" && df.read_only_depends_on && evaluate_read_only_depends_on( df.read_only_depends_on, node.doc ) ) {
                    			status = "Read";
                    		} 
                            return status;
                        },
                        change: async function(i){
                            //Ловим событие изменения данных
            				if (( this.value != this.last_value ) || 
            				    (this.value && this.value != this.df.node[this.df.fieldname]) ){
            				    console.log("Field changed");
            				    let old_value = this.df.node[this.df.fieldname];
            				    this.df.node[this.df.fieldname] = this.validate(this.value);
            				    //Сохраняем новые данные в БД
                				await saveNodeData(this.df.node.value, this.df.fieldname, this.value, old_value, this );
            				}
            			}
                    },
                    value: ev.data.node[ev.data.field_name],
                    render_input: true
                });
                $(control.$input).trigger( "focus" );
                
                if ( !node.controls ) {
                    node.controls = {};
                }
                
                node.controls[ field_name ] = control;
            });
        } );
    }
        
    //Открыть задачу при двойном клике
    if ( field_name == "subject" ) {
        element.on( "dblclick", { node: node, field_name: field_name }, function( ev ) {
            console.log("control dblclick: " + ev.data );
            frappe.set_route("Form", "Task", ev.data.node.value );
        });
    }
}

async function saveNodeData(docName,fieldName,value, oldValue=null, control=null ) {
    var data = {};
    
    if ( Array.isArray( fieldName ) && Array.isArray( value ) ) {
        for (let i = 0; i < fieldName.length; i++) {
            data[ fieldName[ i ] ] = value[ i ];
        }
    } else {
        data[ fieldName ] = value;
    }
    
    frappe.db.set_value('Task', docName, data)
    .then(function(r) {
		console.log("Изменение сохранено.");
		frappe.model.clear_doc("Task", docName);
        frappe.show_alert({
            message:__('Данные успешно обновлены'),
            indicator:'green'
        }, 5);
        if ( control && !Array.isArray( value ) ) {
            let cell = $( control.parent );
            cell.removeClass( toClass( oldValue ) );
            cell.addClass( toClass( value ) );
        }
        update_node_gantt( cur_tree, cur_tree?.nodes[ docName ]?.data );
        refresh_task_dependencies( cur_tree?.root_value, cur_tree?.nodes[ docName ]?.data );
    }).catch(function(e) {
        console.error(e);
        //frappe.throw(`Произошла ошибка при сохранении документа: ${e.message}`);
        if ( oldValue ) {
            if ( !Array.isArray( oldValue ) ) { oldValue = [ oldValue ] };
            if ( !Array.isArray( fieldName ) ) { fieldName = [ fieldName ] };
            
            for (let i = 0; i < oldValue.length; i++) {
                setNodeValue(docName, fieldName[ i ], oldValue[ i ]);
            }
            
            update_node_gantt( cur_tree, cur_tree?.nodes[ docName ]?.data );
            refresh_task_dependencies( cur_tree?.root_value, cur_tree?.nodes[ docName ]?.data );
        }
    });
    
}

function setNodeValue(node_id, field, value) {
    let node = cur_tree.nodes[ node_id ];
    if ( node && node.data ) {
        node.data[ field ] = value;
        let element = node.$row.find('.details-cell.' + field);
        let formatted = frappe.format( value, {'fieldtype': frappe.meta.get_field( "Task", field ).fieldtype } );
        
        if ( node.data.controls ) {
            let control =  node.data.controls[ field ];
            if ( control ) {
                control.set_value( value );
            } else {
                element.text( formatted );
            }
        } else {
            element.text( formatted );
        }
    }
}

//Функция-обертка вокруг стандартного обработчика создания вложенной задачи
function addNodeDecorator(func) {
    return function(x) {
        console.log("addNodeDecorator");
        // Особенная обработка для корневого узла
        if (x.is_root) {
            // Для корневого узла создаем обычную задачу
            frappe.new_doc("Task", {
                project: cur_tree?.view?.page?.fields_dict?.project.get_value(),
                is_group: 0 
            });
            return;
        }
        
        var needWrite = !x.expandable;
        var canWrite = x.data.can_write;
        
        if (needWrite && canWrite) {
            x.expandable = true;
        }
        cur_tree.set_selected_node(x);
        let result = func(x);
        return result;
    };
}

function toolbarRedesign(tree) {
    //Изменение оформления и логики работы стандартных кнопок тулбара
    //Иконки: https://fontawesome.com/v4/icons/
    for (const btn of tree.toolbar) {
        switch( btn.label ) {
            case __("Edit"):
                btn.btnClass = "fa fa-pencil-square-o";
                btn.label = " ";
                break;
            case __("Add Child"):
                btn.btnClass = "fa fa-plus-square-o";
                btn.label = " ";
                btn.condition = function (node) { 
                    return frappe.model.can_create("Task") && node.data.can_write;
                };
                btn.click = addNodeDecorator( btn.click );
                break;
            case __("Delete"):
                btn.btnClass = "fa fa-trash-o";
                btn.label = " ";
                btn.condition = function (node) { 
                    return frappe.model.can_delete("Task") && frappe.perm.has_perm("Task", 0, "delete", node.value);
                };
                break;
            default:
        }
    }
}

