function getStatuses(data) {
    var options = frappe.meta.get_field("Task","status").options.split("\n");
    
    if ( data ) {
        if ( data.confirm) {
            if ( data.owner != frappe.session.user ) {
                const index = options.indexOf("Completed");
                if ( index > -1 ) {
                    options.splice(index, 1); // 2nd parameter means remove one item only
                }
            }
        }
    } 
    
    return options;
}

